FILES = {
    'modules/customizations/src/com/xaulinxs/customizations/qsb/QsbAction.kt': '/*\n * XaulinXs Customizations — não faz parte do AOSP original.\n *\n * Modelo de ação estruturada produzido pelo QsbIntentParser a partir do\n * texto digitado no Modo Texto da QSB. É o "JSON inteligente" da\n * arquitetura pedida pelo usuário: uma representação estruturada e\n * tipada da intenção reconhecida, que o chamador (OseWidgetView)\n * traduz para um Intent real do Android e executa.\n *\n * Fica em memória como sealed class em vez de String JSON serializada\n * de propósito — mesmo conceito (ação estruturada, não texto livre),\n * mas sem overhead de serialização/parsing dentro do mesmo processo.\n * Se algum dia for preciso persistir ou logar a ação (histórico de\n * comandos, por exemplo), dá pra serializar QsbAction para JSON depois\n * sem mudar o parser.\n */\npackage com.xaulinxs.customizations.qsb\n\nimport java.io.Serializable\n\n/**\n * Serializable propositalmente: precisa atravessar um Intent extra ao\n * abrir XaulinXsQsbPermissionActivity (pedido de permissão de\n * contatos em Activity dedicada — ver comentário lá) e voltar depois\n * que o usuário concede/nega, para reexecutar o comando original sem\n * o usuário digitar de novo.\n */\nsealed class QsbAction : Serializable {\n\n    /** Abrir um app pelo nome, sem ação específica dentro dele. */\n    data class OpenApp(val appQuery: String) : QsbAction()\n\n    /** Ligar para um número discado diretamente no texto. */\n    data class CallNumber(val number: String) : QsbAction()\n\n    /** Ligar para um contato salvo, resolvido por nome. */\n    data class CallContact(val contactQuery: String) : QsbAction()\n\n    /** Chamada de voz pelo WhatsApp para número discado diretamente (sinal "whatsapp" + "ligar" combinados). */\n    data class WhatsAppCallNumber(val number: String) : QsbAction()\n\n    /** Chamada de voz pelo WhatsApp para um contato salvo, resolvido por nome. */\n    data class WhatsAppCallContact(val contactQuery: String) : QsbAction()\n\n    /** Mandar mensagem no WhatsApp para um número discado diretamente. */\n    data class WhatsAppNumber(val number: String, val message: String) : QsbAction()\n\n    /** Mandar mensagem no WhatsApp para um contato salvo, resolvido por nome. */\n    data class WhatsAppContact(val contactQuery: String, val message: String) : QsbAction()\n\n    /** Mandar SMS para um número discado diretamente. */\n    data class SmsNumber(val number: String, val message: String) : QsbAction()\n\n    /** Mandar SMS para um contato salvo, resolvido por nome. */\n    data class SmsContact(val contactQuery: String, val message: String) : QsbAction()\n\n    /** Abrir um app e, dentro dele, disparar uma pesquisa por [query]. */\n    data class SearchInApp(val appQuery: String, val query: String) : QsbAction()\n\n    /** Nenhum comando reconhecido — chamador decide o fallback (Modo Web / texto livre). */\n    data object Unrecognized : QsbAction()\n}\n',
    'modules/customizations/src/com/xaulinxs/customizations/qsb/QsbIntentParser.kt': '/*\n * XaulinXs Customizations — não faz parte do AOSP original.\n *\n * "QSB Super Inteligente" v2 — motor de intenção por PRESENÇA DE\n * PALAVRAS-CHAVE, não por prefixo rígido de frase.\n *\n * Por que a v1 (prefixo rígido, "a frase tem que começar com o verbo\n * exato") não bastava: o usuário quer reconhecimento pelo SENTIDO —\n * se o texto contém "ligar" + o nome de um contato, é uma ligação,\n * não importa a ordem ou as palavras ao redor. Se contém "whatsapp" +\n * "ligar"/"chamar", é uma CHAMADA por WhatsApp (voz/vídeo), não uma\n * mensagem de texto — combinação de sinais, não só o primeiro que\n * bater. E não pode ficar restrito a uma lista fixa de apps: "abrir\n * <qualquer coisa> e pesquisar <algo>" tem que funcionar pra\n * QUALQUER app instalado, resolvido dinamicamente contra o\n * AllAppsStore, nunca contra uma lista hardcoded tipo\n * ["youtube","spotify","netflix"].\n *\n * Decisão de arquitetura mantida da v1: nada de libjni_latinime.so —\n * aquela lib é motor de autocorreção/previsão de teclado (n-gramas),\n * sem conceito de ação. Este parser continua sendo regras leves\n * on-device, só que agora por classificação de tokens em vez de regex\n * de frase inteira.\n *\n * Arquitetura do motor:\n *   1) Tokeniza o texto inteiro (minúsculo, sem pontuação nas bordas).\n *   2) Classifica quais CATEGORIAS de sinal estão presentes:\n *      SIGNAL_CALL ("ligar", "chamar", "discar", "telefonar", ...),\n *      SIGNAL_WHATSAPP ("whatsapp", "whats", "zap", "zapzap"),\n *      SIGNAL_MESSAGE ("mensagem", "manda", "envia", "escreve", ...),\n *      SIGNAL_SMS ("sms"),\n *      SIGNAL_OPEN ("abrir", "abre", "open"),\n *      SIGNAL_SEARCH ("pesquisar", "pesquisa", "buscar", "busca",\n *      "procurar", "procura").\n *   3) Combina os sinais presentes para decidir o ActionKind:\n *      WHATSAPP + CALL         -> chamada de voz pelo WhatsApp\n *      WHATSAPP (sem CALL)     -> mensagem de texto pelo WhatsApp\n *      SMS                     -> mensagem de texto por SMS\n *      CALL (sem WHATSAPP)     -> ligação pela discadora nativa\n *      OPEN + SEARCH           -> abrir app + pesquisar dentro dele\n *      OPEN (sem SEARCH)       -> abrir app\n *      nenhum sinal reconhecido-> Unrecognized (cai pro Modo Web)\n *   4) Extrai o ALVO (nome de contato/número, ou nome de app+query)\n *      removendo do texto os tokens de sinal já consumidos — sobra só\n *      o que importa (nome, número, mensagem, termo de busca).\n *\n * Resolução de app continua fora deste arquivo (QsbActionExecutor),\n * contra o AllAppsStore real — nunca uma lista fixa de nomes de app.\n */\npackage com.xaulinxs.customizations.qsb\n\nobject QsbIntentParser {\n\n    private val CALL_SIGNAL_WORDS =\n        setOf("ligar", "ligue", "liga", "chamar", "chama", "discar", "disca", "telefonar", "telefona", "call")\n    private val WHATSAPP_SIGNAL_WORDS = setOf("whatsapp", "whats", "zap", "zapzap")\n    private val SMS_SIGNAL_WORDS = setOf("sms")\n    private val MESSAGE_SIGNAL_WORDS =\n        setOf("mensagem", "manda", "mandar", "envia", "enviar", "escreve", "escrever", "msg")\n    private val OPEN_SIGNAL_WORDS = setOf("abrir", "abre", "abra", "open")\n    private val SEARCH_SIGNAL_WORDS = setOf("pesquisar", "pesquisa", "pesquise", "buscar", "busca", "busque", "procurar", "procura", "procure")\n\n    // Palavras de função sem valor semântico próprio: descartadas ao\n    // montar o alvo (nome/mensagem/query), senão "para o João" vira\n    // alvo "para o João" em vez de só "João".\n    private val STOPWORDS =\n        setOf(\n            "para", "pra", "pro", "o", "a", "os", "as", "um", "uma", "no", "na", "nos", "nas",\n            "com", "de", "do", "da", "por", "pelo", "pela", "sobre", "e", "meu", "minha", "meus", "minhas",\n            "que", "diz", "dizendo", "falando", "falar", "escrito", "escrevendo",\n        )\n\n    // Prefixo "número"/"numero" falado antes de um número discado\n    // ("ligar pro número 11987654321") — descartado ao normalizar.\n    private val NUMBER_WORD_PREFIXES = setOf("número", "numero", "num")\n\n    private val NUMBER_REGEX = Regex("^[+\\\\d][\\\\d\\\\s()-]{5,}$")\n\n    /**\n     * Ponto de entrada único. [rawInput] é o texto exatamente como\n     * está no campo agora — chamado a cada tecla digitada (para o\n     * badge preditivo) e de novo no Enter (para executar de fato).\n     * Determinístico: mesmo texto sempre produz o mesmo QsbAction.\n     */\n    @JvmStatic\n    fun parse(rawInput: String): QsbAction {\n        val trimmed = rawInput.trim()\n        if (trimmed.isEmpty()) return QsbAction.Unrecognized\n\n        val tokens = tokenize(trimmed)\n        if (tokens.isEmpty()) return QsbAction.Unrecognized\n\n        val hasCall = tokens.any { it in CALL_SIGNAL_WORDS }\n        val hasWhatsapp = tokens.any { it in WHATSAPP_SIGNAL_WORDS }\n        val hasSms = tokens.any { it in SMS_SIGNAL_WORDS }\n        val hasMessage = tokens.any { it in MESSAGE_SIGNAL_WORDS }\n        val hasOpen = tokens.any { it in OPEN_SIGNAL_WORDS }\n        val hasSearch = tokens.any { it in SEARCH_SIGNAL_WORDS }\n\n        // Ordem de decisão = ordem de prioridade quando mais de uma\n        // categoria de sinal aparece no mesmo texto.\n        return when {\n            // WhatsApp + sinal de chamada -> chamada de voz pelo\n            // WhatsApp, não mensagem de texto (combinação de sinais,\n            // não o primeiro que bateu).\n            hasWhatsapp && hasCall -> buildRecipientAction(tokens, ::qsbWhatsAppCall)\n\n            // WhatsApp sem sinal de chamada -> mensagem de texto,\n            // mesmo sem a palavra "mensagem"/"manda" explícita (ex.:\n            // "whatsapp emily tudo bem" do exemplo do usuário).\n            hasWhatsapp -> buildRecipientAction(tokens, ::qsbWhatsAppMessage)\n\n            hasSms -> buildRecipientAction(tokens, ::qsbSms)\n\n            // "mensagem"/"manda"/"envia" sem WhatsApp nem SMS\n            // explícitos assume SMS (canal nativo do Android) —\n            // continua sendo uma mensagem de texto de verdade, nunca\n            // cai pro Modo Web só por faltar o nome do canal.\n            hasMessage -> buildRecipientAction(tokens, ::qsbSms)\n\n            hasCall -> buildRecipientAction(tokens, ::qsbCall)\n\n            hasOpen && hasSearch -> buildSearchInAppAction(trimmed, tokens)\n\n            hasOpen -> buildOpenAppAction(tokens)\n\n            // Sem nenhum verbo de ação reconhecido, mas ainda assim\n            // pode ser "abrir app" implícito (usuário só digitou o\n            // nome do app, sem dizer "abrir") — não é um sinal\n            // confiável o suficiente pra badge/execução automática\n            // nesta versão, então cai pra Unrecognized -> Modo Web.\n            else -> QsbAction.Unrecognized\n        }\n    }\n\n    private fun qsbWhatsAppCall(recipient: String): QsbAction =\n        if (looksLikeNumber(recipient)) {\n            QsbAction.WhatsAppCallNumber(normalizeNumber(recipient))\n        } else {\n            QsbAction.WhatsAppCallContact(recipient)\n        }\n\n    private fun qsbWhatsAppMessage(recipient: String, message: String): QsbAction =\n        if (looksLikeNumber(recipient)) {\n            QsbAction.WhatsAppNumber(normalizeNumber(recipient), message)\n        } else {\n            QsbAction.WhatsAppContact(recipient, message)\n        }\n\n    private fun qsbSms(recipient: String, message: String): QsbAction =\n        if (looksLikeNumber(recipient)) {\n            QsbAction.SmsNumber(normalizeNumber(recipient), message)\n        } else {\n            QsbAction.SmsContact(recipient, message)\n        }\n\n    private fun qsbCall(recipient: String): QsbAction =\n        if (looksLikeNumber(recipient)) {\n            QsbAction.CallNumber(normalizeNumber(recipient))\n        } else {\n            QsbAction.CallContact(recipient)\n        }\n\n    /**\n     * Monta uma ação "só destinatário" (chamadas), delegando para\n     * [build]. Usado quando a ação não carrega corpo de mensagem.\n     */\n    private inline fun buildRecipientAction(tokens: List<String>, build: (String) -> QsbAction): QsbAction {\n        val recipient = extractRecipient(tokens)\n        if (recipient.isBlank()) return QsbAction.Unrecognized\n        return build(recipient)\n    }\n\n    /**\n     * Sobrecarga para ações "destinatário + mensagem" (WhatsApp/SMS\n     * texto). [build] recebe (destinatário, corpo da mensagem) —\n     * corpo pode ser vazio (abre o app já na conversa certa, sem\n     * texto pré-preenchido, quando o usuário não escreveu nada além\n     * do nome).\n     */\n    private inline fun buildRecipientAction(\n        tokens: List<String>,\n        build: (String, String) -> QsbAction,\n    ): QsbAction {\n        val (recipient, message) = extractRecipientAndMessage(tokens)\n        if (recipient.isBlank()) return QsbAction.Unrecognized\n        return build(recipient, message)\n    }\n\n    /**\n     * Extrai o destinatário removendo todos os tokens de sinal\n     * conhecidos (ligar/whatsapp/sms/mensagem/abrir/pesquisar) e\n     * stopwords — o que sobra é o nome/número. Não tenta separar\n     * mensagem aqui (usado só por ações sem corpo de mensagem).\n     */\n    private fun extractRecipient(tokens: List<String>): String {\n        val allSignalWords =\n            CALL_SIGNAL_WORDS + WHATSAPP_SIGNAL_WORDS + SMS_SIGNAL_WORDS + MESSAGE_SIGNAL_WORDS +\n                OPEN_SIGNAL_WORDS + SEARCH_SIGNAL_WORDS\n        return tokens\n            .filter { it !in allSignalWords && it !in STOPWORDS }\n            .joinToString(" ")\n            .trim()\n    }\n\n    /**\n     * Extrai destinatário + mensagem para ações WhatsApp/SMS. Como o\n     * motor agora é por palavra-chave (não posição fixa na frase), a\n     * heurística é: se houver um conector explícito de mensagem\n     * ("dizendo"/"falando"/":"), tudo antes dele é destinatário e\n     * tudo depois é mensagem. Sem conector explícito (ex.: "whatsapp\n     * emily tudo bem"), assume o PRIMEIRO token restante como nome do\n     * contato e o resto como mensagem — cobre o caso mais comum sem\n     * exigir acesso à agenda dentro do parser (que não conhece\n     * Android de propósito, pra continuar testável isoladamente).\n     * Nomes compostos sem conector explícito ("Ana Paula, oi") ficam\n     * fora desta primeira versão; o caminho recomendado nesse caso é\n     * usar "dizendo"/"falando" para marcar onde o nome termina.\n     */\n    private fun extractRecipientAndMessage(tokens: List<String>): Pair<String, String> {\n        val allSignalWords =\n            CALL_SIGNAL_WORDS + WHATSAPP_SIGNAL_WORDS + SMS_SIGNAL_WORDS + MESSAGE_SIGNAL_WORDS +\n                OPEN_SIGNAL_WORDS + SEARCH_SIGNAL_WORDS\n        val remaining = tokens.filter { it !in allSignalWords }\n\n        val messageConnectorIndex = remaining.indexOfFirst { it == "dizendo" || it == "falando" || it == ":" }\n        if (messageConnectorIndex >= 0) {\n            val recipientTokens = remaining.subList(0, messageConnectorIndex).filter { it !in STOPWORDS }\n            val messageTokens = remaining.subList(messageConnectorIndex + 1, remaining.size)\n            return recipientTokens.joinToString(" ").trim() to messageTokens.joinToString(" ").trim()\n        }\n\n        val meaningful = remaining.filter { it !in STOPWORDS }\n        if (meaningful.isEmpty()) return "" to ""\n        val recipient = meaningful.first()\n        val message = meaningful.drop(1).joinToString(" ").trim()\n        return recipient to message\n    }\n\n    private fun buildOpenAppAction(tokens: List<String>): QsbAction {\n        val appQuery = tokens.filter { it !in OPEN_SIGNAL_WORDS && it !in STOPWORDS }.joinToString(" ").trim()\n        if (appQuery.isBlank()) return QsbAction.Unrecognized\n        return QsbAction.OpenApp(appQuery)\n    }\n\n    /**\n     * "abrir <app> e pesquisar <query>" — como o app não vem mais de\n     * uma lista fixa, a extração aqui é posicional dentro do texto\n     * ORIGINAL (preserva capitalização, útil pra query de busca):\n     * tudo entre o verbo de abrir e o verbo de busca é candidato a\n     * nome de app; tudo depois do verbo de busca é a query. Resolução\n     * de qual token exatamente é o app de verdade (contra apps\n     * instalados) acontece no executor.\n     */\n    private fun buildSearchInAppAction(original: String, tokens: List<String>): QsbAction {\n        val lower = original.lowercase()\n        val openWord = OPEN_SIGNAL_WORDS.firstOrNull { word -> tokens.contains(word) } ?: return QsbAction.Unrecognized\n        val searchWord = SEARCH_SIGNAL_WORDS.firstOrNull { word -> tokens.contains(word) } ?: return QsbAction.Unrecognized\n\n        val openIndex = lower.indexOf(openWord)\n        if (openIndex < 0) return QsbAction.Unrecognized\n        val afterOpen = original.substring(openIndex + openWord.length)\n        val afterOpenLower = afterOpen.lowercase()\n        val searchMatch = Regex("\\\\b${Regex.escape(searchWord)}\\\\b").find(afterOpenLower) ?: return QsbAction.Unrecognized\n        val searchIndexInRemainder = searchMatch.range.first\n\n        var appPart = afterOpen.substring(0, searchIndexInRemainder).trim()\n        // Remove conector "e" solto entre o app e o verbo de busca\n        // ("Chrome e" -> "Chrome"), com ou sem espaço remanescente.\n        if (appPart.lowercase().endsWith(" e")) appPart = appPart.dropLast(2).trim()\n        val andIndex = appPart.lowercase().lastIndexOf(" e ")\n        if (andIndex >= 0) appPart = appPart.substring(0, andIndex).trim()\n        // Descarta artigos/possessivos soltos antes do nome de app de\n        // verdade (ex.: "meu navegador Chrome" -> "Chrome") — nome de\n        // app na fala coloquial é tipicamente a última palavra.\n        appPart = appPart.substringAfterLast(\' \').trim()\n\n        var query = afterOpen.substring(searchIndexInRemainder + searchWord.length).trim()\n        for (prep in listOf("por ", "sobre ", "de ")) {\n            if (query.lowercase().startsWith(prep)) {\n                query = query.substring(prep.length).trim()\n                break\n            }\n        }\n        if (appPart.isBlank() || query.isBlank()) return QsbAction.Unrecognized\n        return QsbAction.SearchInApp(appPart, query)\n    }\n\n    // ------------------------------------------------------------------\n    // Helpers\n    // ------------------------------------------------------------------\n\n    private fun tokenize(text: String): List<String> =\n        text\n            .lowercase()\n            .split(Regex("\\\\s+"))\n            .map { it.trim(\',\', \'.\', \'!\', \'?\', \';\') }\n            .filter { it.isNotEmpty() }\n\n    private fun looksLikeNumber(text: String): Boolean = NUMBER_REGEX.matches(stripNumberPrefix(text).trim())\n\n    private fun stripNumberPrefix(text: String): String {\n        val trimmed = text.trim()\n        val firstWord = trimmed.substringBefore(\' \')\n        return if (firstWord.lowercase() in NUMBER_WORD_PREFIXES) {\n            trimmed.substringAfter(\' \').trim()\n        } else {\n            trimmed\n        }\n    }\n\n    private fun normalizeNumber(text: String): String = stripNumberPrefix(text).filter { it.isDigit() || it == \'+\' }\n}\n',
    'modules/customizations/src/com/xaulinxs/customizations/qsb/QsbActionExecutor.kt': '/*\n * XaulinXs Customizations — não faz parte do AOSP original.\n *\n * Traduz um QsbAction (saída do QsbIntentParser) em execução real:\n * resolve apps contra o AllAppsStore, resolve contatos contra\n * QsbContactResolver, monta o Intent certo para cada ação, e reporta\n * de volta ao chamador (OseWidgetView) o que fazer — incluindo pedir\n * uma permissão em falta, quando for o caso.\n *\n * Este arquivo não chama startActivity/requestPermissions diretamente:\n * devolve um ExecutionOutcome selado e quem efetivamente dispara a UI\n * é o chamador, que já tem acesso à Activity/View corretos. Mantém a\n * separação: parser não sabe de Android, executor não sabe de UI.\n */\npackage com.xaulinxs.customizations.qsb\n\nimport android.content.Context\nimport android.content.Intent\nimport android.net.Uri\nimport com.android.launcher3.allapps.AllAppsStore\nimport com.android.launcher3.model.data.AppInfo\n\nsealed class QsbExecutionOutcome {\n    /** Intent pronto para ser disparado pelo chamador. */\n    data class Launch(val intent: Intent) : QsbExecutionOutcome()\n\n    /** Falta uma permissão de runtime para completar a ação. */\n    data class NeedsPermission(val permission: String, val retryAction: QsbAction) :\n        QsbExecutionOutcome()\n\n    /** Reconheceu a intenção mas não conseguiu resolver o alvo (app/contato). */\n    data class ResolutionFailed(val reason: QsbFailureReason) : QsbExecutionOutcome()\n\n    /** Não reconheceu nenhum comando — chamador decide fallback. */\n    data object Unrecognized : QsbExecutionOutcome()\n}\n\nenum class QsbFailureReason {\n    APP_NOT_FOUND,\n    CONTACT_NOT_FOUND,\n}\n\nobject QsbActionExecutor {\n\n\n    @JvmStatic\n    fun execute(context: Context, action: QsbAction, appsStore: AllAppsStore): QsbExecutionOutcome =\n        when (action) {\n            is QsbAction.Unrecognized -> QsbExecutionOutcome.Unrecognized\n\n            is QsbAction.OpenApp -> resolveApp(appsStore, action.appQuery)?.let {\n                QsbExecutionOutcome.Launch(it.intent)\n            } ?: QsbExecutionOutcome.ResolutionFailed(QsbFailureReason.APP_NOT_FOUND)\n\n            is QsbAction.SearchInApp ->\n                resolveApp(appsStore, action.appQuery)?.let { app ->\n                    QsbExecutionOutcome.Launch(buildSearchIntent(context, app, action.query))\n                } ?: QsbExecutionOutcome.ResolutionFailed(QsbFailureReason.APP_NOT_FOUND)\n\n            is QsbAction.CallNumber ->\n                QsbExecutionOutcome.Launch(buildCallIntent(action.number))\n\n            is QsbAction.CallContact -> resolveContactOrRequestPermission(context, action, action.contactQuery) { number ->\n                buildCallIntent(number)\n            }\n\n            // WhatsApp não expõe deep link público/oficial para iniciar\n            // uma LIGAÇÃO de voz/vídeo diretamente (só existe API\n            // documentada para abrir a conversa) — confirmado: não há\n            // um esquema tipo "whatsapp://call?phone=..." suportado.\n            // Em vez de fingir automação que não existe (ou depender de\n            // ActivityClass não-documentada, que quebra em qualquer\n            // atualização do WhatsApp), abre a CONVERSA do contato já\n            // pronta — o usuário só precisa tocar no ícone de chamada\n            // dentro dela, um toque a mais em vez de zero.\n            is QsbAction.WhatsAppCallNumber ->\n                QsbExecutionOutcome.Launch(buildWhatsAppIntent(action.number, ""))\n\n            is QsbAction.WhatsAppCallContact -> resolveContactOrRequestPermission(context, action, action.contactQuery) { number ->\n                buildWhatsAppIntent(number, "")\n            }\n\n            is QsbAction.WhatsAppNumber ->\n                QsbExecutionOutcome.Launch(buildWhatsAppIntent(action.number, action.message))\n\n            is QsbAction.WhatsAppContact -> resolveContactOrRequestPermission(context, action, action.contactQuery) { number ->\n                buildWhatsAppIntent(number, action.message)\n            }\n\n            is QsbAction.SmsNumber ->\n                QsbExecutionOutcome.Launch(buildSmsIntent(action.number, action.message))\n\n            is QsbAction.SmsContact -> resolveContactOrRequestPermission(context, action, action.contactQuery) { number ->\n                buildSmsIntent(number, action.message)\n            }\n        }\n\n    /**\n     * Compartilhado pelos três tipos de ação "por contato": checa\n     * permissão, resolve o nome, e delega a montagem do Intent final\n     * para [buildIntent] uma vez que o número é conhecido. Devolve\n     * NeedsPermission com a própria [action] original em\n     * [QsbExecutionOutcome.NeedsPermission.retryAction] para o\n     * chamador poder re-executar exatamente o mesmo comando assim que\n     * a permissão for concedida, sem o usuário ter que digitar de novo.\n     */\n    private inline fun resolveContactOrRequestPermission(\n        context: Context,\n        action: QsbAction,\n        contactQuery: String,\n        buildIntent: (phoneNumber: String) -> Intent,\n    ): QsbExecutionOutcome {\n        if (!QsbContactResolver.hasContactsPermission(context)) {\n            return QsbExecutionOutcome.NeedsPermission(android.Manifest.permission.READ_CONTACTS, action)\n        }\n        val resolved = QsbContactResolver.resolve(context, contactQuery)\n            ?: return QsbExecutionOutcome.ResolutionFailed(QsbFailureReason.CONTACT_NOT_FOUND)\n        return QsbExecutionOutcome.Launch(buildIntent(resolved.phoneNumber))\n    }\n\n    /**\n     * Resolução tolerante contra o AllAppsStore real (nunca uma lista\n     * fixa de nomes) — cobre nome exato, prefixo, "contém", e por\n     * fim "todas as palavras da query aparecem em algum lugar do\n     * título do app" (cobre queries como "navegador chrome" batendo\n     * em "Google Chrome", mesmo com token extra que não faz parte do\n     * nome real do app).\n     */\n    private fun resolveApp(appsStore: AllAppsStore, query: String): AppInfo? {\n        val apps = appsStore.apps ?: emptyArray()\n        val queryLower = query.trim().lowercase()\n        if (queryLower.isEmpty()) return null\n\n        apps.firstOrNull { it.title?.toString()?.lowercase() == queryLower }?.let { return it }\n        apps.firstOrNull { it.title?.toString()?.lowercase()?.startsWith(queryLower) == true }\n            ?.let { return it }\n        apps.firstOrNull { it.title?.toString()?.lowercase()?.contains(queryLower) == true }\n            ?.let { return it }\n\n        val queryWords = queryLower.split(Regex("\\\\s+")).filter { it.isNotBlank() }\n        if (queryWords.size > 1) {\n            apps.firstOrNull { app ->\n                val title = app.title?.toString()?.lowercase() ?: return@firstOrNull false\n                queryWords.any { word -> title.contains(word) }\n            }?.let { return it }\n        }\n        return null\n    }\n\n    private fun buildCallIntent(number: String): Intent =\n        Intent(Intent.ACTION_CALL, Uri.parse("tel:$number"))\n\n    private fun buildSmsIntent(number: String, message: String): Intent =\n        Intent(Intent.ACTION_SENDTO, Uri.parse("smsto:$number")).apply {\n            if (message.isNotBlank()) putExtra("sms_body", message)\n        }\n\n    /**\n     * Usa o esquema de deep link público do WhatsApp (api.whatsapp.com/send)\n     * em vez de um Intent de package explícito — funciona tanto com\n     * WhatsApp quanto WhatsApp Business (o usuário escolhe se tiver os\n     * dois), e não exige declarar consulta de pacote específico no\n     * Manifest (Android 11+ visibilidade de pacotes).\n     */\n    private fun buildWhatsAppIntent(number: String, message: String): Intent {\n        val digitsOnly = number.filter { it.isDigit() }\n        val uriBuilder = Uri.parse("https://api.whatsapp.com/send").buildUpon()\n        uriBuilder.appendQueryParameter("phone", digitsOnly)\n        if (message.isNotBlank()) uriBuilder.appendQueryParameter("text", message)\n        return Intent(Intent.ACTION_VIEW, uriBuilder.build())\n    }\n\n    /**\n     * Pesquisa dentro de um app específico. Tenta primeiro\n     * ACTION_WEB_SEARCH restrito ao pacote do app (padrão que\n     * navegadores e vários apps de busca reconhecem, com o texto em\n     * SearchManager.QUERY). Só usa setPackage() se o PackageManager\n     * confirmar que o próprio app resolve essa action — sem essa\n     * checagem, setPackage() para um app sem esse handler derruba o\n     * launcher com ActivityNotFoundException em vez de abrir algo.\n     * Sem handler de busca dedicado, cai para abrir o app normalmente\n     * (o intent principal dele) — nunca abre um app diferente do\n     * pedido, só não consegue pré-preencher a pesquisa.\n     */\n    private fun buildSearchIntent(context: Context, app: AppInfo, query: String): Intent {\n        val packageName = app.componentName?.packageName\n        if (packageName != null) {\n            val webSearchIntent =\n                Intent(Intent.ACTION_WEB_SEARCH).apply {\n                    putExtra(android.app.SearchManager.QUERY, query)\n                    setPackage(packageName)\n                }\n            val resolved =\n                context.packageManager.resolveActivity(webSearchIntent, android.content.pm.PackageManager.MATCH_DEFAULT_ONLY)\n            if (resolved != null) return webSearchIntent\n        }\n        return app.intent\n    }\n}\n',
    'src/com/android/launcher3/qsb/OseWidgetView.kt': '/*\n * Copyright (C) 2025 The Android Open Source Project\n *\n * Licensed under the Apache License, Version 2.0 (the "License");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *      http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an "AS IS" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\npackage com.android.launcher3.qsb\n\nimport android.annotation.SuppressLint\nimport android.app.AlertDialog\nimport android.appwidget.AppWidgetManager.INVALID_APPWIDGET_ID\nimport android.appwidget.AppWidgetProviderInfo\nimport android.content.ComponentName\nimport android.content.Context\nimport android.content.Intent\nimport android.content.pm.PackageManager\nimport android.content.res.ColorStateList\nimport android.os.Process.myUserHandle\nimport android.text.Editable\nimport android.text.TextWatcher\nimport android.util.AttributeSet\nimport android.util.Log\nimport android.view.View\nimport android.widget.EditText\nimport android.widget.ImageView\nimport android.widget.LinearLayout\nimport android.widget.RemoteViews\nimport android.widget.TextView\nimport androidx.annotation.VisibleForTesting\nimport androidx.core.net.toUri\nimport com.android.launcher3.BubbleTextView\nimport com.android.launcher3.LauncherSettings.Favorites\nimport com.android.launcher3.R\nimport com.android.launcher3.allapps.AllAppsStore\nimport com.android.launcher3.dagger.LauncherComponentProvider.appComponent\nimport com.android.launcher3.model.data.AppInfo\nimport com.android.launcher3.model.data.ItemInfo\nimport com.android.launcher3.model.data.LauncherAppWidgetInfo\nimport com.android.launcher3.popup.PopupContainer\nimport com.android.launcher3.util.ComponentKey\nimport com.android.launcher3.util.RunnableList\nimport com.android.launcher3.util.SafeCloseable\nimport com.android.launcher3.util.ViewEx.registerLifecycleTask\nimport com.android.launcher3.views.ActivityContext\nimport com.android.launcher3.widget.LauncherAppWidgetHostView\nimport com.xaulinxs.customizations.qsb.QsbAction\nimport com.xaulinxs.customizations.qsb.QsbActionPreviewBuilder\nimport com.xaulinxs.customizations.qsb.QsbBadgeIcon\nimport com.xaulinxs.customizations.qsb.QsbConfig\nimport com.xaulinxs.customizations.qsb.QsbFailureReason\nimport com.xaulinxs.customizations.qsb.QsbTextModeCommand\nimport com.xaulinxs.customizations.qsb.QsbTextModeResult\nimport com.xaulinxs.customizations.qsb.XaulinXsQsbPermissionActivity\nimport com.xaulinxs.customizations.qsb.XaulinXsQsbPermissionCallback\n\n/**\n * Renders the On-device search engine\'s widget [RemoteViews] based on [AppWidgetProviderInfo] by\n * listening to OSE changes through [OseWidgetManager]\n */\nclass OseWidgetView\n@JvmOverloads\nconstructor(context: Context, attrs: AttributeSet? = null, defStyleAttr: Int = 0) :\n    LauncherAppWidgetHostView(context) {\n\n    private val oseWidgetManager = context.appComponent.oseWidgetManager\n    @VisibleForTesting var closeActions = RunnableList()\n    private val activityContext: ActivityContext = ActivityContext.lookupContext(context)\n\n    internal var autoUpdateTag = true\n\n    init {\n        activityContext.appWidgetHolder?.onViewCreationCallback?.accept(this)\n        setOnLongClickListener {\n            PopupContainer.showForMenuItems(\n                activityContext,\n                this,\n                activityContext.activityComponent.getOseWidgetOptionsProvider().getOptionItems(),\n            ) != null\n        }\n    }\n\n    override fun onAttachedToWindow() {\n        super.onAttachedToWindow()\n        attachedToWindow()\n    }\n\n    @VisibleForTesting\n    fun attachedToWindow() {\n        closeActions.executeAllAndClear()\n\n        // XaulinXs Customizations: esta é a QSB nativa AOSP/Launcher3\n        // "NoQuickstep" — OseWidgetManager nunca mais localiza/binda um\n        // AppWidget de terceiro (ver comentário em\n        // OseWidgetManager.handleOseInfoUpdate), então providerInfo e\n        // views são sempre despachados como null. O fluxo original do\n        // AOSP abaixo pressupõe que, depois de setAppWidget(id, info)\n        // com um "info" real, um evento de "views" real chega logo em\n        // seguida sobrescrevendo o RemoteViews(context.packageName, 0)\n        // usado só como placeholder de reset — com info sempre null,\n        // esse RemoteViews vazio (layoutId=0) nunca é sobrescrito e\n        // fica permanentemente visível, o que o framework renderiza\n        // como uma UI de erro nativa genérica (não a nossa\n        // getErrorView() customizada — essa só dispara quando\n        // updateAppWidget recebe null, não um RemoteViews vazio).\n        // Fix: quando não há provider (it == null), pula esse reset\n        // por completo e delega direto para getErrorView(), chamando\n        // updateAppWidget(null) — o caminho que o framework já trata\n        // corretamente.\n        //\n        // We use INVALID_APPWIDGET_ID because appWidgetId is not tracked in OseWidgetView. Instead\n        // it is managed by OseWidgetManager and QsbAppWidgetHost.\n        closeActions.add(\n            oseWidgetManager.providerInfo.forEach(activityContext.uiExecutor) {\n                setAppWidget(INVALID_APPWIDGET_ID, it)\n                if (it == null) {\n                    updateAppWidget(null)\n                } else {\n                    // We will get valid updateAppWidget remoteview call from\n                    // OseWidgetManager again. This is only for resetting the\n                    // remoteviews using a broken remote view.\n                    updateAppWidget(RemoteViews(context.packageName, 0))\n                }\n                if (autoUpdateTag) tag = getTagInfo(it)\n                Log.i(TAG, "setAppWidget providerInfo=$it")\n            }::close\n        )\n        closeActions.add(\n            oseWidgetManager.views.forEach(activityContext.uiExecutor) {\n                updateAppWidget(it)\n                Log.i(TAG, "updateAppWidget view=$it")\n            }::close\n        )\n    }\n\n    override fun onDetachedFromWindow() {\n        super.onDetachedFromWindow()\n        detachedFromWindow()\n    }\n\n    @VisibleForTesting\n    fun detachedFromWindow() {\n        closeActions.executeAllAndClear()\n    }\n\n    override fun shouldDelayChildPressedState(): Boolean {\n        // Delay the ripple effect on the widget view when swiping up from home screen\n        // to go to all apps.\n        return true\n    }\n\n    @SuppressLint("UseCompatLoadingForDrawables")\n    override fun getErrorView(): View {\n        val view =\n            View.inflate(context, R.layout.ose_default_bubbletext_layout, null) as BubbleTextView\n        applyXaulinXsQsbAppearance(view)\n        val oseInfo = context.appComponent.getOseManager().oseInfo.value\n        val osePkg: String? =\n            when {\n                oseInfo.isOseConfigured -> oseInfo.pkg\n                else -> null\n            }\n\n        val appsStore = activityContext.activityComponent.appsStore\n        val title = context.getText(R.string.abandoned_search)\n        val updateListener =\n            AllAppsStore.OnUpdateListener {\n                val appInfo =\n                    osePkg\n                        ?.let {\n                            appsStore.getApp(\n                                ComponentKey(ComponentName(osePkg, ""), myUserHandle()),\n                                AppInfo.PACKAGE_KEY_COMPARATOR,\n                            )\n                        }\n                        ?.clone()\n\n                if (appInfo == null) {\n                    view.tag = null\n                    view.applyIconAndLabel(\n                        context.getDrawable(R.drawable.ic_allapps_search)!!.mutate().apply {\n                            setTint(context.getColor(R.color.materialColorOnSurface))\n                        },\n                        title,\n                        null,\n                    )\n                    // Since we don\'t have a valid appInfo, just open the default browser\n                    // Set the data to a blank page uri\n                    view.setOnClickIntent(Intent(Intent.ACTION_VIEW).setData("http://".toUri()))\n                } else {\n                    appInfo.title = title\n                    view.applyFromApplicationInfo(appInfo)\n                    view.setOnClickIntent(\n                        when {\n                            // Launch search intent.\n                            oseInfo.supportsSearchIntent ->\n                                Intent(Intent.ACTION_SEARCH).setPackage(appInfo.targetPackage)\n                            // Launch main activity\n                            else -> appInfo.intent\n                        }\n                    )\n                }\n            }\n\n        updateListener.onAppsUpdated()\n        view.registerLifecycleTask {\n            appsStore.addUpdateListener(updateListener)\n            SafeCloseable { appsStore.removeUpdateListener(updateListener) }\n        }\n        return view\n    }\n\n    /**\n     * XaulinXs Customizations: aplica os 4 sliders da QsbConfigActivity\n     * (Tamanho, Largura, Transparência, Cor) na view inflada da QSB.\n     * Tamanho e Largura são independentes (por isso dois sliders\n     * separados em vez de uma única "escala"): Tamanho escala a view\n     * inteira (scaleX/scaleY, mantém proporção); Largura reduz só a\n     * largura via layout_weight fracionário, então dá pra ter uma QSB\n     * mais estreita sem achatar o texto/ícone.\n     */\n    private fun applyXaulinXsQsbAppearance(view: BubbleTextView) {\n        val sizeFraction = QsbConfig.getSizePercent(context) / 100f\n        view.scaleX = sizeFraction\n        view.scaleY = sizeFraction\n\n        val widthFraction = QsbConfig.getWidthPercent(context) / 100f\n        (view.layoutParams as? LinearLayout.LayoutParams)?.let { params ->\n            params.weight = widthFraction\n            view.layoutParams = params\n        }\n\n        val transparencyPercent = QsbConfig.getTransparencyPercent(context)\n        view.alpha = 1f - (transparencyPercent / 100f)\n\n        view.backgroundTintList = ColorStateList.valueOf(QsbConfig.getBarColor(context))\n    }\n\n    fun View.setOnClickIntent(intent: Intent) = setOnClickListener {\n        // XaulinXs Customizations: Modo Texto e Modo Web são exclusivos\n        // (QsbConfig.MODE_TEXT_ENABLED). No Modo Texto, o toque abre um\n        // campo de texto: se reconhecer um comando ("abrir <app>"),\n        // executa direto; senão cai pro comportamento normal do Modo\n        // Web (o mesmo intent que já seria disparado), nunca deixa o\n        // toque sem efeito.\n        if (QsbConfig.isTextModeEnabled(context)) {\n            showXaulinXsTextModeDialog(intent)\n            return@setOnClickListener\n        }\n        launchQsbIntent(intent)\n    }\n\n    /**\n     * XaulinXs Customizations — "Predictive Action Badge": conforme o\n     * usuário digita, o texto é reprocessado (QsbActionPreviewBuilder)\n     * e uma etiqueta abaixo do campo mostra a ação que será executada\n     * — antes de apertar Enter. Construído em código (não em um XML\n     * do AOSP como search_container_all_apps.xml) para não editar um\n     * layout grande do launcher e ficar 100% contido no pacote\n     * XaulinXs Customizations.\n     */\n    private fun View.showXaulinXsTextModeDialog(fallbackIntent: Intent) {\n        val appsStore = activityContext.activityComponent.appsStore\n\n        val badgeIcon =\n            ImageView(context).apply {\n                layoutParams =\n                    LinearLayout.LayoutParams(dp(16), dp(16)).apply { marginEnd = dp(8) }\n            }\n        val badgeText =\n            TextView(context).apply {\n                textSize = 12f\n                setTextColor(context.getColor(R.color.materialColorPrimary))\n                setTypeface(typeface, android.graphics.Typeface.BOLD)\n            }\n        val badgeContainer =\n            LinearLayout(context).apply {\n                orientation = LinearLayout.HORIZONTAL\n                gravity = android.view.Gravity.CENTER_VERTICAL\n                setPadding(dp(12), dp(6), dp(12), dp(6))\n                setBackgroundResource(R.drawable.xaulinxs_qsb_action_badge_bg)\n                visibility = View.GONE\n                addView(badgeIcon)\n                addView(badgeText)\n            }\n\n        val input =\n            EditText(context).apply {\n                hint = context.getString(R.string.xaulinxs_qsb_text_mode_hint)\n                setPadding(48, 32, 48, 32)\n            }\n\n        val outerContainer =\n            LinearLayout(context).apply {\n                orientation = LinearLayout.VERTICAL\n                addView(input)\n                addView(\n                    badgeContainer,\n                    LinearLayout.LayoutParams(\n                        LinearLayout.LayoutParams.MATCH_PARENT,\n                        LinearLayout.LayoutParams.WRAP_CONTENT,\n                    ).apply { topMargin = dp(4) },\n                )\n            }\n\n        input.addTextChangedListener(\n            object : TextWatcher {\n                override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}\n                override fun afterTextChanged(s: Editable?) {}\n                override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {\n                    val preview = QsbActionPreviewBuilder.build(appsStore, s?.toString().orEmpty())\n                    if (preview == null) {\n                        badgeContainer.visibility = View.GONE\n                        return\n                    }\n                    badgeText.text = preview.message\n                    badgeIcon.setImageResource(iconResFor(preview.icon))\n                    badgeContainer.visibility = View.VISIBLE\n                }\n            }\n        )\n\n        AlertDialog.Builder(context)\n            .setTitle(R.string.xaulinxs_qsb_text_mode_dialog_title)\n            .setView(outerContainer)\n            .setPositiveButton(android.R.string.ok) { _, _ ->\n                val raw = input.text?.toString().orEmpty()\n                if (raw.isBlank()) {\n                    launchQsbIntent(fallbackIntent)\n                    return@setPositiveButton\n                }\n                handleXaulinXsTextModeResult(\n                    QsbTextModeCommand.interpret(raw, appsStore, context),\n                    fallbackIntent,\n                )\n            }\n            .setNegativeButton(android.R.string.cancel, null)\n            .show()\n    }\n\n    private fun View.dp(value: Int): Int =\n        (value * context.resources.displayMetrics.density).toInt()\n\n    private fun iconResFor(icon: QsbBadgeIcon): Int =\n        when (icon) {\n            QsbBadgeIcon.OPEN_APP -> android.R.drawable.ic_menu_manage\n            QsbBadgeIcon.CALL -> android.R.drawable.ic_menu_call\n            QsbBadgeIcon.WHATSAPP_CALL -> android.R.drawable.ic_menu_call\n            QsbBadgeIcon.MESSAGE -> android.R.drawable.ic_menu_send\n            QsbBadgeIcon.SEARCH -> android.R.drawable.ic_menu_search\n            QsbBadgeIcon.NONE -> android.R.drawable.ic_menu_search\n        }\n\n    /**\n     * Trata o resultado da QSB Inteligente. FreeText (nenhum comando\n     * reconhecido) é o único caso que cai para o Modo Web\n     * ([fallbackIntent]) — todo o resto é uma ação concreta reconhecida\n     * (lançada, pendente de permissão, ou alvo não encontrado), nunca\n     * um fallback genérico de busca/browser no lugar da ação pedida.\n     */\n    private fun View.handleXaulinXsTextModeResult(result: QsbTextModeResult, fallbackIntent: Intent) {\n        when (result) {\n            is QsbTextModeResult.Launch -> launchQsbIntent(result.intent)\n            is QsbTextModeResult.FreeText -> launchQsbIntent(fallbackIntent)\n            is QsbTextModeResult.NotFound -> showXaulinXsNotFoundToast(result.reason)\n            is QsbTextModeResult.NeedsPermission ->\n                requestXaulinXsPermission(result.permission, result.retryAction)\n        }\n    }\n\n    private fun showXaulinXsNotFoundToast(reason: QsbFailureReason) {\n        val messageRes =\n            when (reason) {\n                QsbFailureReason.APP_NOT_FOUND -> R.string.xaulinxs_qsb_smart_app_not_found\n                QsbFailureReason.CONTACT_NOT_FOUND -> R.string.xaulinxs_qsb_smart_contact_not_found\n            }\n        android.widget.Toast.makeText(context, messageRes, android.widget.Toast.LENGTH_SHORT).show()\n    }\n\n    /**\n     * Pede a permissão em falta via diálogo explicativo + Activity\n     * transparente dedicada (XaulinXsQsbPermissionActivity), em vez de\n     * pedir a permissão diretamente pelo Launcher: o Launcher não\n     * implementa onRequestPermissionsResult, e adicionar esse override\n     * nele mexeria num arquivo grande do AOSP com alto risco de\n     * conflito em atualizações futuras. A Activity dedicada resolve o\n     * pedido e devolve o resultado via callback estático de curta\n     * duração (XaulinXsQsbPermissionCallback), reexecutando\n     * [retryAction] automaticamente se concedida — usuário não precisa\n     * digitar o comando de novo.\n     */\n    private fun requestXaulinXsPermission(permission: String, retryAction: QsbAction) {\n        AlertDialog.Builder(context)\n            .setTitle(R.string.xaulinxs_qsb_smart_permission_title)\n            .setMessage(R.string.xaulinxs_qsb_smart_permission_message)\n            .setPositiveButton(R.string.xaulinxs_storage_permission_grant) { _, _ ->\n                val appsStore = activityContext.activityComponent.appsStore\n                XaulinXsQsbPermissionCallback.onGranted = { grantedAction ->\n                    // retry() só devolve FreeText no caso defensivo de a\n                    // ação reconhecida virar Unrecognized (não deveria\n                    // acontecer para uma action já validada pelo parser) —\n                    // nesse cenário não há intent de fallback sensato, só\n                    // ignora silenciosamente em vez de arriscar um crash\n                    // com um Intent vazio.\n                    when (val result = QsbTextModeCommand.retry(grantedAction, appsStore, context)) {\n                        is QsbTextModeResult.FreeText -> Unit\n                        else -> handleXaulinXsTextModeResult(result, Intent())\n                    }\n                }\n                context.startActivity(\n                    XaulinXsQsbPermissionActivity.newIntent(context, permission, retryAction)\n                        .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)\n                )\n            }\n            .setNegativeButton(R.string.xaulinxs_storage_permission_deny, null)\n            .show()\n    }\n\n    private fun View.launchQsbIntent(intent: Intent) {\n        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED)\n        if (intent.action == Intent.ACTION_VIEW) {\n            // Browser Intent and set the default browser package.\n            val resolveInfo =\n                runCatching {\n                        context.packageManager.resolveActivity(\n                            intent,\n                            PackageManager.MATCH_DEFAULT_ONLY,\n                        )\n                    }\n                    .getOrNull()\n            resolveInfo?.activityInfo?.packageName.apply { intent.setPackage(this) }\n        }\n        activityContext.startActivitySafely(\n            this@OseWidgetView,\n            intent,\n            this@OseWidgetView.tag as? ItemInfo,\n        )\n    }\n\n    private class QsbItemInfo : ItemInfo() {\n\n        override fun getStableId() = STABLE_ID\n    }\n\n    companion object {\n        private const val TAG = "OseWidgetView"\n\n        private val STABLE_ID = Object()\n\n        private fun getTagInfo(provider: AppWidgetProviderInfo?): ItemInfo {\n            val info =\n                provider?.let { LauncherAppWidgetInfo(INVALID_APPWIDGET_ID, it.provider) }\n                    ?: QsbItemInfo()\n            info.id = R.id.search_container_hotseat\n            info.container = Favorites.CONTAINER_HOTSEAT\n            return info\n        }\n    }\n}\n',
}

MARKERS = {
    'modules/customizations/src/com/xaulinxs/customizations/qsb/QsbAction.kt': 'WhatsAppCallNumber',
    'modules/customizations/src/com/xaulinxs/customizations/qsb/QsbIntentParser.kt': 'PRESENÇA DE',
    'modules/customizations/src/com/xaulinxs/customizations/qsb/QsbActionExecutor.kt': 'WhatsAppCallNumber',
    'src/com/android/launcher3/qsb/OseWidgetView.kt': 'import com.xaulinxs.customizations.qsb.XaulinXsQsbPermissionCallback',
}


def run(cmd, cwd):
    result = subprocess.run(cmd, cwd=cwd, text=True)
    if result.returncode != 0:
        sys.exit(f"Comando falhou: {' '.join(cmd)}")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--repo", default="~/Launcher3",
        help="Caminho do checkout local (padrao: ~/Launcher3)",
    )
    parser.add_argument(
        "--skip-build", action="store_true",
        help="Nao rodar ./gradlew assembleNoQuickstepDebug ao final",
    )
    args = parser.parse_args()

    repo = Path(args.repo).expanduser().resolve()
    if not repo.is_dir():
        sys.exit(f"Repo nao encontrado em {repo}. Use --repo <caminho>.")

    fixed, already, missing = [], [], []
    for rel_path, content in FILES.items():
        target = repo / rel_path
        if not target.is_file():
            missing.append(rel_path)
            continue

        current = target.read_text(encoding="utf-8")
        marker = MARKERS[rel_path]
        if marker in current and current == content:
            already.append(rel_path)
            continue

        target.write_text(content, encoding="utf-8")
        fixed.append(rel_path)

    print()
    if fixed:
        print("Arquivos corrigidos:")
        for p in fixed:
            print(f"  + {p}")
    if already:
        print("Ja estavam corretos (idempotente, pulados):")
        for p in already:
            print(f"  = {p}")
    if missing:
        print("AVISO -- nao encontrados neste checkout (pulados):")
        for p in missing:
            print(f"  ! {p}")

    if not fixed and not missing:
        print("\nNada a fazer -- tudo ja estava correto.")

    if not args.skip_build:
        print("\nCompilando (./gradlew assembleNoQuickstepDebug)...")
        gradlew = repo / "gradlew"
        if not gradlew.is_file():
            sys.exit("gradlew nao encontrado no repo -- pulei o build.")
        run(["chmod", "+x", "gradlew"], cwd=repo)
        run(["./gradlew", "assembleNoQuickstepDebug"], cwd=repo)
        print("\nBuild OK.")
    else:
        print("\n--skip-build: pulei a compilacao.")

    print(
        "\nSe o build passar, testar no Modo Texto da QSB:\n"
        "  1) digitar 'ligar para ' e ver o badge aparecer em tempo real\n"
        "  2) 'ligar para Ana' e 'Ana ligar' -- ambos devem reconhecer igual\n"
        "  3) 'whatsapp ligar para <contato>' -- abre a conversa no WhatsApp\n"
        "     (nao inicia a chamada sozinho -- toque no icone dentro da conversa;\n"
        "     limitacao real do WhatsApp, sem deep link oficial pra chamada)\n"
        "  4) 'whatsapp emily tudo bem' -- mensagem 'tudo bem' pra Emily\n"
        "  5) 'abrir Chrome e pesquisar gatos' -- abre com a busca pronta\n"
        "  6) texto sem nenhum comando -- cai pro Modo Web normalmente"
    )


if __name__ == "__main__":
    main()
